  // Builds one dropdown menu (a fixed-position .proj-menu opened from any element matching `trigger`).
  // Wired by event delegation so triggers can be re-rendered; each menu only reacts to its own items.
  function createDropdownMenu({ id, extraClass, groups, trigger, onPick }) {
    const menu = document.createElement('div');
    menu.className = 'proj-menu' + (extraClass ? ' ' + extraClass : '');
    menu.id = id;
    menu.setAttribute('role', 'menu');
    menu.hidden = true;
    menu.innerHTML = groups.map(group => `
      <div class="proj-menu-group">${group.map(item => `
        <button type="button" class="proj-menu-item" role="menuitem" data-action="${item.action || ''}">
          <img src="${PROJ_MENU_ICONS[item.icon]}" alt="">
          <span>${item.label}</span>${item.hint ? `<span class="hint">${item.hint}</span>` : ''}
        </button>`).join('')}
      </div>`).join('<div class="proj-menu-sep" role="separator"></div>');
    document.body.appendChild(menu);

    let anchor = null;
    function close() {
      if (!anchor) return;
      menu.hidden = true;
      anchor.setAttribute('aria-expanded', 'false');
      anchor = null;
    }
    function open(btn) {
      anchor = btn;
      menu.hidden = false;
      btn.setAttribute('aria-expanded', 'true');
      // Right edge lines up with the trigger, 4px below it (as in the Figma frame).
      const r = btn.getBoundingClientRect();
      const w = menu.offsetWidth;
      menu.style.left = Math.max(8, Math.min(r.right - w, window.innerWidth - w - 8)) + 'px';
      menu.style.top = (r.bottom + 4) + 'px';
    }

    document.addEventListener('click', (e) => {
      const menuItem = e.target.closest('.proj-menu-item');
      if (menuItem && menu.contains(menuItem)) {
        const from = anchor;
        close();
        onPick(menuItem.dataset.action, from);
        return;
      }
      const btn = e.target.closest(trigger);
      if (!btn) { close(); return; }
      const wasOpen = anchor === btn;
      close();
      if (!wasOpen) open(btn);
    });
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape' || !anchor) return;
      const btn = anchor;
      close();
      btn.focus();
    });
    window.addEventListener('resize', close);
    window.addEventListener('scroll', close, true);
  }

  // Gear button in the board toolbar → project settings.
  createDropdownMenu({
    id: 'projSettingsMenu',
    groups: PROJ_MENU_GROUPS,
    trigger: '[data-project-settings]',
    onPick: (action, from) => {
      if (action === 'settings') openProjectSettings(CURRENT_KAN_PROJECT);
      else if (action === 'status') openStatusManager({ returnFocusTo: from });
      else if (action === 'type') openTypeManager({ returnFocusTo: from });
      else if (action === 'roles') openRoleManager(CURRENT_KAN_PROJECT, { returnFocusTo: from });
      else if (action === 'members') openMemberManager(CURRENT_KAN_PROJECT, { returnFocusTo: from });
      else showToast('ฟีเจอร์นี้ยังไม่พร้อมใช้งานใน prototype นี้');
    }
  });

