  function projDonutStyle(segments) {
    let acc = 0;
    const stops = segments.map(s => {
      const start = acc; acc += s.pct;
      return `${s.color} ${start}% ${acc}%`;
    }).join(', ');
    return `background: conic-gradient(${stops});`;
  }

  function buildProjectCard(cfg) {
    const statsHtml = cfg.stats.map(s => `
      <div class="proj-stat-row">
        <span class="dot" style="background:${s.color}"></span>
        <span class="lbl">${s.label} :</span>
        <span class="pct">${s.pctText}</span>
        <span>| ${s.count}</span>
      </div>
    `).join('');

    const donutSegments = cfg.stats.filter(s => s.pct > 0).map(s => ({ pct: s.pct, color: s.color }));
    if (donutSegments.length === 0) donutSegments.push({ pct: 100, color: '#3a3a3a' });

    const tasksHtml = cfg.tasks && cfg.tasks.length ? `
      <div class="proj-tasks-list">
        ${cfg.tasks.map(t => `
          <div class="proj-task-row">
            <div class="left">
              <span class="proj-task-key">${t.key}</span>
              <span class="proj-task-title">${t.title}</span>
              ${t.status ? `<span class="proj-task-status" style="background:${t.status.color}">${t.status.label}</span>` : ''}
            </div>
            ${t.dot ? '<span class="proj-task-dot"></span>' : ''}
          </div>
        `).join('')}
      </div>
    ` : `
      <div class="proj-tasks-empty">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 7h16l-1.5 12a2 2 0 0 1-2 1.8H7.5a2 2 0 0 1-2-1.8L4 7z"/><path d="M9 7V5a3 3 0 0 1 6 0v2"/></svg>
        <span>ยังไม่มีแจ้งเตือน</span>
      </div>
    `;

    const bodyHtml = `
      <div class="proj-stats-card">
        <div class="proj-stats-inner">
          <div class="proj-stats-list">${statsHtml}</div>
          <div class="proj-donut" style="${projDonutStyle(donutSegments)}">
            <div class="hole"><span class="l">งานทั้งหมด</span><span class="n">${cfg.total}</span></div>
          </div>
        </div>
      </div>
      <div class="proj-vdivider"></div>
      <div class="proj-tasks-wrap">${tasksHtml}</div>
    `;

    const inviteOverlay = cfg.state === 'invite' ? `
      <div class="proj-invite-overlay">
        <div class="msg">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="5" width="18" height="14" rx="2"/><polyline points="3 7 12 13 21 7"/></svg>
          คุณถูกเชิญเข้าร่วมโปรเจกต์
        </div>
        <div class="proj-invite-actions">
          <button class="proj-invite-decline" data-stub="1">ปฎิเสธ</button>
          <button class="proj-invite-join" data-stub="1">เข้าร่วม</button>
        </div>
      </div>
    ` : '';

    const card = document.createElement('div');
    card.className = 'proj-card';
    card.innerHTML = `
      <div class="proj-avatar-box">
        <div class="proj-avatar" style="background:${cfg.avatarBg};">${cfg.avatarContent}</div>
        <span class="pname">${cfg.name}</span>
      </div>
      <div class="proj-body" style="${cfg.state === 'invite' ? 'filter: blur(15px);' : ''}">${bodyHtml}</div>
      ${inviteOverlay}
      <button class="proj-more" aria-label="ตัวเลือกเพิ่มเติม" data-stub="1">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="5" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="12" cy="19" r="1.3"/></svg>
      </button>
    `;
    card.querySelectorAll('[data-stub]').forEach(el => {
      el.addEventListener('click', (e) => { e.stopPropagation(); showToast('ฟีเจอร์นี้ยังไม่พร้อมใช้งานใน prototype นี้'); });
    });
    return card;
  }

